INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 1, 'theory', 'Как устроена сеть: узлы, каналы и пакеты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 1, 0, 'Чем коммутация пакетов выгоднее коммутации каналов?', '["Канал резервируется под каждого пользователя навсегда","Пока один узел молчит, освободившуюся ёмкость используют другие","Пакеты никогда не теряются","Задержка всегда равна нулю"]', 1, 'Статистическое мультиплексирование: пакеты разных пользователей делят канал и заполняют паузы друг друга.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 1, 1, 'Из каких слагаемых складывается задержка пакета на одном звене?', '["Только из времени передачи","Из скорости света и числа хостов","Из обработки, очереди, передачи и распространения","Из размера заголовка и длины имени узла"]', 2, 'Четыре компонента: обработка заголовка, ожидание в очереди, передача L/R и распространение сигнала.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 1, 2, 'Сколько секунд занимает передача пакета в L бит по каналу R бит/с?', '["L / R","L · R","R / L","L + R"]', 0, 'Время передачи — это размер пакета, делённый на скорость канала.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 1, 3, 'Что делает маршрутизатор, когда буфер полностью заполнен?', '["Увеличивает скорость канала","Откладывает пакет на час","Сжимает все пакеты в очереди","Отбрасывает новые пакеты"]', 3, 'Буфер конечен; потеря — нормальный способ сказать отправителю «притормози».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 1, 4, 'Что такое BDP — произведение пропускной способности на задержку?', '["Число хостов в сети","Количество бит, одновременно находящихся в канале","Предельный размер кадра Ethernet","Разброс задержек между пакетами"]', 1, 'Это ёмкость канала: столько бит «в пути» одновременно; если слать меньше, канал простаивает.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 2, 'theory', 'Модели OSI и TCP/IP: уровни и инкапсуляция');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 2, 0, 'Что происходит с данными при отправке вниз по стеку?', '["Каждый уровень удаляет заголовок предыдущего","Данные шифруются на каждом уровне","Каждый уровень добавляет свой заголовок: данные заворачиваются в конверты","Данные копируются в несколько потоков"]', 2, 'Это инкапсуляция: сегмент → пакет → кадр, на каждом уровне свой заголовок.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 2, 1, 'До какого уровня разворачивает кадр обычный коммутатор?', '["До канального","До прикладного","До транспортного","До сетевого"]', 0, 'Коммутатор смотрит на мак-адрес в канальном заголовке и не читает пакет внутри.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 2, 2, 'Что остаётся неизменным, когда пакет проходит через маршрутизатор?', '["Мак-адреса отправителя и получателя","Контрольная сумма кадра","Тип кадра и размер","Ай-пи-адреса отправителя и получателя"]', 3, 'IP-адреса сквозные; кадр на каждом звене собирается заново, с новыми мак-адресами (меняется ещё TTL).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 2, 3, 'Какой уровень стека TCP/IP выбирает программу-получателя по номеру порта?', '["Канальный","Транспортный","Сетевой","Физический"]', 1, 'Порт — поле заголовка TCP или UDP, то есть транспортного уровня.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 2, 4, 'Вы видите, что ping не проходит, а кабель подключён и индикатор горит. С чего продолжить поиск по правилу «снизу вверх»?', '["Проверить код приложения","Переустановить браузер","Проверить порт сервиса и файрвол","Проверить порт коммутатора, мак-адреса, затем адрес, маску и маршрут"]', 3, 'После физического уровня идёт канальный, потом сетевой; транспорт и приложение проверяют в последнюю очередь.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 3, 'theory', 'Канальный уровень: Ethernet, MAC-адреса, коммутаторы и Wi-Fi');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 3, 0, 'Что делает коммутатор, получив кадр с неизвестным MAC-адресом получателя?', '["Отбрасывает его","Рассылает копии на все остальные порты","Отправляет на ближайший порт","Отвечает отправителю ошибкой"]', 1, 'Это флуд: пока адрес не выучен, кадр идёт на все порты, кроме входного.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 3, 1, 'Как коммутатор заполняет таблицу MAC-адресов?', '["Запоминает MAC получателей","Берёт адреса из настроек администратора","Запоминает MAC отправителя и порт, с которого пришёл кадр","Запрашивает адреса у маршрутизатора"]', 2, 'Источник данных — поле «MAC отправителя» в приходящих кадрах.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 3, 2, 'Чем опасна петля в сети коммутаторов?', '["Широковещательные кадры бесконечно ходят по кругу — шторм","Кадры идут слишком медленно","Таблица MAC очищается","Скорость каналов падает вдвое"]', 0, 'Широковещательные кадры размножаются, и сеть захлёбывается; от этого защищает STP.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 3, 3, 'Что делает транк между двумя коммутаторами?', '["Увеличивает скорость кабеля","Объединяет все VLAN в один","Шифрует трафик","Несёт кадры нескольких VLAN по одному кабелю, помечая их номером VLAN"]', 3, 'На транке каждый кадр получает метку 802.1Q с номером VLAN.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 3, 4, 'Почему в Wi-Fi вместо обнаружения коллизий используют их избегание?', '["Wi-Fi всегда работает в дуплексе","Устройство не слышит чужих во время собственной передачи","Коллизий в радиоэфире не бывает","Так быстрее передавать большие файлы"]', 1, 'Собственный сигнал заглушает чужой: поэтому ждут свободный эфир и подтверждают кадры.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 4, 'theory', 'IP-адресация: IPv4, маски, CIDR, NAT и IPv6');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 4, 0, 'Сколько адресов доступно узлам в сети 192.168.1.0/24?', '["256","255","128","254"]', 3, 'Из 256 адресов один — адрес сети (все нули в части узла), один — широковещательный (все единицы).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 4, 1, 'Какой адрес сети у узла 10.0.5.77 с маской /26?', '["10.0.5.64","10.0.5.0","10.0.5.76","10.0.5.128"]', 0, 'Маска /26 даёт блоки по 64 адреса: 0, 64, 128, 192. Адрес 77 лежит в блоке, который начинается с 64.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 4, 2, 'Какие из адресов частные, то есть не маршрутизируются в интернете?', '["8.8.8.8 и 1.1.1.1","100.100.100.100","172.20.0.5 и 192.168.3.1","224.0.0.5"]', 2, 'Частные диапазоны: 10/8, 172.16–172.31 и 192.168/16. Остальные адреса — публичные, групповые или оператора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 4, 3, 'Что делает NAT-шлюз с исходящим пакетом?', '["Шифрует его целиком","Подменяет адрес и порт отправителя на свои и запоминает соответствие","Снижает его TTL до нуля","Превращает IPv4 в IPv6"]', 1, 'Запись в таблице трансляций позволяет вернуть ответ внутреннему узлу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 4, 4, 'Компьютер 192.168.1.10/24 отправляет пакет на 8.8.8.8. Кому он отдаст кадр?', '["Прямо серверу 8.8.8.8","Шлюзу по умолчанию (MAC шлюза, IP получателя 8.8.8.8)","Любому соседу по сети","DHCP-серверу"]', 1, 'Получатель вне подсети: MAC — шлюза, а IP-адрес получателя остаётся прежним.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 5, 'theory', 'Маршрутизация: таблицы, ARP, ICMP и traceroute');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 5, 0, 'В таблице есть записи 10.0.0.0/8 → R1, 10.1.0.0/16 → R2 и 0.0.0.0/0 → R3. Куда уйдёт пакет для 10.1.2.3?', '["К R2","К R1","К R3","Отбросится"]', 0, 'Подходят /8, /16 и маршрут по умолчанию; побеждает самый длинный префикс — /16.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 5, 1, 'Что меняется в пакете, когда он проходит маршрутизатор?', '["Адреса отправителя и получателя","TTL уменьшается на единицу (и пересчитывается сумма заголовка)","Ничего не меняется","Номер порта"]', 1, 'Меняется ещё канальный заголовок, но IP-адреса остаются; TTL — на единицу меньше.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 5, 2, 'Зачем нужен ARP?', '["Узнать IP-адрес по имени","Сообщить об ошибке маршрутизации","Узнать MAC-адрес следующего шага по его IP-адресу","Построить таблицу маршрутов"]', 2, 'ARP-запрос широковещательный, ответ приходит одному отправителю и сохраняется в ARP-кэше.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 5, 3, 'Как traceroute узнаёт адреса маршрутизаторов на пути?', '["Читает их таблицы по сети","Использует специальный протокол трассировки в каждом маршрутизаторе","Запрашивает у провайдера","Шлёт пакеты с TTL 1, 2, 3… и читает адреса из ICMP time exceeded"]', 3, 'Каждый маршрутизатор, у которого TTL дошёл до нуля, присылает отправителю ICMP time exceeded со своим адресом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 5, 4, 'Ping на удалённый сервер доходит до него, но ответа нет. Какая причина наиболее вероятна?', '["На сервере нет обратного маршрута к вашей сети","У пакета слишком большой TTL","Адрес получателя частный","ARP-кэш переполнен"]', 0, 'Ответ — тоже пакет: если на обратном пути нет записи про вашу подсеть, он потеряется.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 6, 'theory', 'UDP и сокеты: датаграммы без гарантий');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 6, 0, 'Что именно добавляет заголовок UDP к данным?', '["Номера последовательности и подтверждения","Адреса отправителя и получателя","Окно приёма и флаги соединения","Порт отправителя, порт получателя, длину и контрольную сумму"]', 3, 'Весь заголовок UDP — 8 байт: четыре поля по 2 байта.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 6, 1, 'Клиент отправил датаграмму на порт, где нет программы. Что он получит в лучшем случае?', '["RST от сервера","ICMP «порт недоступен»","Ничего: UDP никогда не сообщает об ошибках","Автоматический повтор на уровне UDP"]', 1, 'Сервер может ответить ICMP; но чаще ответа нет, и приложение полагается на таймаут.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 6, 2, 'Для чего чаще всего выбирают UDP?', '["Для DNS-запросов, голоса, видео и игр, где важны скорость и свежесть","Для скачивания больших файлов без потерь","Для передачи паролей","Для почты"]', 0, 'Потерянную датаграмму дешевле повторить или пропустить, чем держать соединение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 6, 3, 'Что делает сервер сразу после привязки сокета к порту (bind) в простом UDP-сервере?', '["Принимает входящее соединение","Выполняет рукопожатие","Ждёт датаграмму вызовом recvfrom","Закрывает сокет"]', 2, 'У UDP нет соединений: сервер читает датаграммы одну за другой и отвечает отправителю.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 6, 4, 'Почему UDP-датаграммы стараются держать не длиннее ~1200 байт?', '["Так требует стандарт","Длинные датаграммы шифруются медленнее","Порты кончаются","Датаграмма больше MTU фрагментируется, а потеря любого фрагмента убивает всю датаграмму"]', 3, 'Короткие датаграммы проходят без фрагментации.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 7, 'theory', 'TCP: рукопожатие, нумерация байтов и закрытие соединения');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 7, 0, 'Из каких сегментов состоит установление TCP-соединения?', '["ACK, ACK, FIN","SYN, SYN-ACK, ACK","SYN, FIN, RST","SYN, ACK"]', 1, 'Трёхстороннее рукопожатие: клиент — SYN, сервер — SYN-ACK, клиент — ACK.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 7, 1, 'Клиент отправил сегмент с номером 1000 и 100 байтами данных. Какое значение ACK ответит сервер?', '["1000","100","1001","1100"]', 3, 'ACK — номер следующего ожидаемого байта: 1000 + 100 = 1100.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 7, 2, 'При подключении к порту вместо ответа пришёл RST. Что это значит?', '["Узел жив, но на этом порту никто не слушает","Пакеты глотает файрвол","Сервер перегружен","Нужно повторить SYN"]', 0, 'Закрытый порт отвечает RST; молчание — признак фильтра или потерь.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 7, 3, 'Что делает отправитель, получив три одинаковых ACK подряд?', '["Закрывает соединение","Уменьшает MSS","Повторяет потерянный сегмент, не дожидаясь таймера","Начинает рукопожатие заново"]', 2, 'Дубли ACK значат, что один сегмент пропущен, а следующие дошли: быстрая повторная отправка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 7, 4, 'Зачем после закрытия соединения держат состояние TIME_WAIT?', '["Чтобы сохранить пароль","Чтобы закрыть порт на сервере","Чтобы сервер перезапустился","Чтобы запоздавшие сегменты не попали в новое соединение с теми же портами"]', 3, 'Сегменты старого соединения могут ещё блуждать по сети; минута ожидания их отсеивает.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 8, 'theory', 'Надёжность и управление перегрузкой: окна, потери, медленный старт');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 8, 0, 'Окно приёма — 64 КБ, RTT — 100 мс. Какова примерная верхняя граница скорости?', '["около 50 Мбит/с","около 500 Мбит/с","около 5 Мбит/с","ограничена только каналом"]', 2, 'Скорость ≤ окно / RTT = 64 КБ / 0,1 с ≈ 640 КБ/с ≈ 5 Мбит/с.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 8, 1, 'Что происходит с окном перегрузки в фазе медленного старта?', '["Удваивается за круг RTT","Растёт на один сегмент за круг RTT","Остаётся постоянным","Уменьшается вдвое"]', 0, 'Каждый ACK добавляет сегмент, поэтому за один RTT окно удваивается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 8, 2, 'Как реагирует классический Reno на потерю сегмента, обнаруженную по трём одинаковым ACK?', '["Закрывает соединение","Увеличивает окно вдвое","Сбрасывает окно в один сегмент","Уменьшает окно вдвое"]', 3, 'Это мультипликативное уменьшение (AIMD): ÷ 2. К одному сегменту окно сбрасывается только при таймауте.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 8, 3, 'В чём главное отличие BBR от CUBIC?', '["BBR использует UDP","BBR измеряет пропускную способность и задержку канала и почти не реагирует на потери","BBR работает только в IPv6","BBR не требует подтверждений"]', 1, 'Потому BBR хорош на каналах, где потери не связаны с перегрузкой: Wi-Fi, мобильные сети, спутник.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 8, 4, 'Что такое bufferbloat?', '["Раздутие очереди на узком месте: потерь нет, но задержка огромна","Нехватка памяти в браузере","Фрагментация больших пакетов","Ошибка контрольной суммы"]', 0, 'Слишком большой буфер заполняется до краёв, и каждый пакет ждёт в очереди сотни миллисекунд.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 9, 'theory', 'Сокеты в программе: блокирующий ввод-вывод, select, epoll и async');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 9, 0, 'Что возвращает accept() на слушающем сокете?', '["Новый сокет для общения с подключившимся клиентом и его адрес","Данные, присланные клиентом","Номер порта","Ничего: соединение уже принято"]', 0, 'Слушающий сокет остаётся и продолжает принимать, а разговор идёт через сокет, который вернул accept.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 9, 1, 'Клиент трижды вызвал send по 100 байт. Что вернёт один recv(4096) на стороне сервера?', '["Строго первые 100 байт","Ровно 300 байт","Ничего не вернёт до закрытия","От 1 до 300 байт: сколько успело накопиться"]', 3, 'TCP — поток байтов без границ сообщений; recv возвращает то, что есть, но не больше запрошенного.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 9, 2, 'Что означает пустой результат (b'''') вызова recv?', '["Ошибку сети","Таймаут","Собеседник закрыл соединение","Данные ещё не пришли"]', 2, 'Конец потока: другая сторона закрыла соединение (FIN).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 9, 3, 'Какое преимущество у epoll перед потоком на каждого клиента?', '["Не нужны сокеты","Один поток обслуживает множество соединений, а цена зависит от числа готовых сокетов","Данные шифруются","Доставка данных быстрее на сети"]', 1, 'Нет сотен потоков со стеками и переключениями: операционная система сама подсказывает, какие сокеты готовы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 9, 4, 'Почему тяжёлые вычисления нельзя выполнять прямо внутри корутины asyncio?', '["Корутины не умеют считать","Результат расчёта нельзя вернуть","Расчёт остановит цикл событий, и замёрзнут все соединения","Корутина закроет сокет"]', 2, 'Цикл событий работает в одном потоке: пока корутина считает и не делает await, остальные ждут.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 10, 'theory', 'DNS: как имя превращается в адрес');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 10, 0, 'Что делает рекурсивный резолвер, получив вопрос клиента?', '["Отвечает только из своих записей","Передаёт вопрос клиенту другого сервера","Идёт по цепочке: корень, TLD, авторитативный сервер, и возвращает клиенту готовый ответ","Перенаправляет клиента на корневой сервер"]', 2, 'Резолвер выполняет всю итеративную работу за клиента и кэширует полученное.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 10, 1, 'Что означает ответ NXDOMAIN?', '["Такого имени не существует","Сервер недоступен","Запрос отклонён","Ответ есть, но он пустой"]', 0, 'NXDOMAIN — окончательный ответ «имени нет»; недоступный сервер даёт SERVFAIL или тишину.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 10, 2, 'Что делает запись CNAME?', '["Связывает имя с адресом IPv6","Объявляет имя псевдонимом другого имени","Указывает почтовый сервер","Подписывает зону"]', 1, 'Резолвер, встретив CNAME, продолжает поиск уже по новому имени.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 10, 3, 'Для чего служит TTL у DNS-записи?', '["Ограничивает число запросов","Задаёт приоритет сервера","Задаёт, сколько времени её можно хранить в кэше","Определяет тип записи"]', 2, 'По истечении TTL резолвер должен запросить запись заново.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 10, 4, 'У одного пользователя сайт открывается по старому адресу, а у остальных по новому. Что проверить в первую очередь?', '["Запись в файле hosts на его компьютере и кэш его резолвера","Мощность сервера","Размер MTU","Версию HTTP"]', 0, 'hosts побеждает ответ DNS, а резолвер может держать старый ответ до конца TTL.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 11, 'theory', 'HTTP/1.1: запросы, заголовки, коды ответов, кэш и cookie');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 11, 0, 'Какой код ответа означает «ресурс перемещён навсегда»?', '["200","404","503","301"]', 3, '301 Moved Permanently; новый адрес указан в заголовке Location.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 11, 1, 'Какой метод не идемпотентен — повторять его вслепую опасно?', '["POST","GET","PUT","DELETE"]', 0, 'Повторный POST может создать вторую запись или второй заказ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 11, 2, 'Зачем в HTTP/1.1 заголовок Host?', '["Чтобы передать тип содержимого","Чтобы указать, какой сайт нужен, когда на одном IP-адресе работает множество сайтов","Чтобы включить шифрование","Чтобы задать время жизни кэша"]', 1, 'Это основа виртуального хостинга: сервер выбирает сайт по заголовку Host.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 11, 3, 'Сервер ответил 304 Not Modified. Что это значит?', '["Страница удалена","Нужна авторизация","Копия клиента в кэше актуальна — тело можно не передавать","Перенаправление на другой сайт"]', 2, 'Клиент прислал ETag в If-None-Match; сервер подтвердил, что ресурс не изменился.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 11, 4, 'Какой флаг cookie не даёт скриптам на странице прочитать значение?', '["Secure","HttpOnly","SameSite","Path"]', 1, 'HttpOnly защищает идентификатор сессии от кражи через XSS.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 12, 'theory', 'HTTP/2 и HTTP/3: мультиплексирование и QUIC');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 12, 0, 'Что даёт мультиплексирование в HTTP/2?', '["Шифрование всех запросов","Много независимых запросов и ответов по одному соединению, чередуя кадры","Автоматическое кэширование","Замену TCP на UDP"]', 1, 'Потоки идут параллельно по одному соединению: не нужны шесть соединений и очередь.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 12, 1, 'Что такое HPACK?', '["Протокол шифрования","Алгоритм управления перегрузкой","Метод сжатия HTTP-заголовков с общей таблицей","Формат сертификатов"]', 2, 'Повторяющиеся заголовки передаются ссылкой на запись таблицы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 12, 2, 'Почему на сети с потерями HTTP/2 может работать хуже HTTP/1.1?', '["HTTP/2 не умеет повторять потерянное","HTTP/2 использует UDP","HTTP/2 не поддерживает кэш","Потеря одного TCP-сегмента задерживает все потоки на общем соединении"]', 3, 'TCP гарантирует порядок байтов, поэтому дыра блокирует данные всех потоков.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 12, 3, 'Какой транспорт использует HTTP/3?', '["QUIC поверх UDP","TCP","SCTP","ICMP"]', 0, 'QUIC реализует надёжность, потоки и шифрование поверх UDP.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 12, 4, 'Сервер рекламирует HTTP/3, но у клиентов за корпоративным файрволом страница грузится по HTTP/2. Что вероятнее всего?', '["Сертификат просрочен","Закрыт TCP/80","На файрволе закрыт UDP/443","Не работает DNS"]', 2, 'QUIC идёт по UDP/443; если он закрыт, браузер откатывается на TCP.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 13, 'theory', 'TLS и HTTPS: шифрование, сертификаты и доверие');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 13, 0, 'Для чего в TLS используют асимметричную криптографию?', '["Для шифрования всего потока данных","Для подписи и обмена ключами при рукопожатии: общий симметричный секрет","Для сжатия данных","Для DNS-запросов"]', 1, 'Асимметричная криптография медленная, поэтому ею только договариваются о секрете, а данные шифруют быстро — симметрично.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 13, 1, 'Клиент открывает https://www.example.org, а в сертификате только example.org. Что произойдёт?', '["Соединение установится без предупреждений","Браузер подставит нужное имя","Сервер автоматически перевыпустит сертификат","Браузер откажет: имя не совпало с SAN"]', 3, 'Адрес должен совпадать с одним из имён в сертификате (поле SAN).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 13, 2, 'Сертификат сайта открывается у администратора, но у части клиентов — «не удалось построить цепочку». Вероятная причина?', '["Сервер не присылает промежуточный сертификат","Просрочен корневой сертификат","Закрыт порт 443","Устарел DNS"]', 0, 'Часть клиентов достроит цепочку сама, а другие откажутся: сервер обязан присылать промежуточные.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 13, 3, 'Что даёт прямая секретность (forward secrecy)?', '["Ускоряет рукопожатие","Скрывает имя сайта","Кража закрытого ключа позже не позволит расшифровать записанный раньше трафик","Позволяет не проверять сертификаты"]', 2, 'Каждый сеанс использует новый секрет, а долгий ключ только подписывает рукопожатие.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 13, 4, 'Сколько кругов (RTT) после TCP занимает рукопожатие TLS 1.3?', '["Два","Один","Три","Ноль, всегда"]', 1, 'TLS 1.3 тратит один круг; TLS 1.2 — два.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 14, 'theory', 'Веб-API: REST, WebSocket, Server-Sent Events и gRPC');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 14, 0, 'Какой код следует вернуть при успешном создании ресурса через POST?', '["200 OK без заголовков","204 No Content","302 Found","201 Created и заголовок Location с адресом нового ресурса"]', 3, '201 говорит, что ресурс создан, а Location сообщает его адрес.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 14, 1, 'Для чего нужен ключ идемпотентности (Idempotency-Key)?', '["Чтобы повтор POST после потери ответа не создал дубликат","Для шифрования запроса","Чтобы ускорить ответ","Чтобы ограничить частоту запросов"]', 0, 'Сервер второй раз возвращает сохранённый результат по тому же ключу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 14, 2, 'Клиент превысил лимит запросов. Какой ответ ожидаем?', '["401 Unauthorized","429 Too Many Requests с заголовком Retry-After","403 Forbidden","404 Not Found"]', 1, '429 говорит «слишком часто», а Retry-After — через сколько секунд повторить.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 14, 3, 'Какой код возвращает сервер, соглашаясь переключиться на WebSocket?', '["200 OK","301 Moved Permanently","101 Switching Protocols","426 Upgrade Required"]', 2, 'Дальше по тому же TCP-соединению идут кадры WebSocket.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 14, 4, 'Что нужно для новостей от сервера только в одну сторону, если хочется проще и без отдельного протокола?', '["Server-Sent Events: ответ text/event-stream, который сервер не закрывает","gRPC с двусторонним стримом","UDP-мультикаст","Опрос раз в миллисекунду"]', 0, 'SSE работает поверх обычного HTTP, сам переподключается и умеет продолжать с Last-Event-ID.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 15, 'theory', 'Диагностика сети: ping, ss, tcpdump и Wireshark');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 15, 0, 'Пинг на IP-адрес сайта проходит, а по имени — нет. Где искать проблему?', '["В кабеле","В MTU","В DNS: резолвер не отвечает или имя настроено неверно","В сертификате"]', 2, 'Сеть работает (адрес отвечает), значит ломается превращение имени в адрес.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 15, 1, 'В выводе ss сервис слушает 127.0.0.1:80, а клиенты получают отказ. Почему?', '["Сервис привязан только к локальному адресу и снаружи недоступен","Порт 80 зарезервирован","Закончились файловые дескрипторы","Сервис слушает UDP"]', 0, 'Нужен адрес 0.0.0.0 (или адрес интерфейса): тогда подключения извне будут приняты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 15, 2, 'В tcpdump видны только исходящие SYN и ни одного ответа. Что это означает?', '["Соединение установлено","Порт закрыт — пришёл бы RST","Сервер ждёт ACK","Рукопожатие не завершается: пакет теряется или фильтруется по дороге"]', 3, 'Закрытый порт отвечает RST; молчание — признак потери пакета или фильтра.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 15, 3, 'Маленькие запросы проходят, большие ответы зависают. Что проверить в первую очередь?', '["Срок сертификата","Размер MTU по пути и блокировку ICMP «frag needed»","Правила DNS","Скорость диска"]', 1, 'Канал с меньшим MTU и фильтрация ICMP дают именно такую картину; порог видно пингом с -M do.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 15, 4, 'Что значит звёздочка на одном шаге traceroute, если следующие шаги отвечают?', '["Пакеты теряются","Путь оборвался","Маршрутизатор не отвечает на ICMP time exceeded, но пакеты пропускает","Маршрутизатор перезагружается"]', 2, 'Дальнейшие ответы доказывают, что пакеты проходят этот узел.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 16, 'theory', 'Файрволы, прокси и NAT на практике');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 16, 0, 'Что означает правило «пропускать пакеты в состоянии ESTABLISHED» в файрволе с отслеживанием соединений?', '["Разрешить любые новые соединения","Блокировать ответы","Разрешить только ICMP","Разрешить ответы на соединения, уже открытые изнутри"]', 3, 'Так клиенты внутри ходят наружу, а извне новые соединения не принимаются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 16, 1, 'На шлюзе настроен проброс 8080 → 192.168.0.10:80, но снаружи не работает. Политика FORWARD — DROP. Что нужно разрешить в FORWARD?', '["Внутренний адрес 192.168.0.10 и порт 80 — DNAT срабатывает до фильтра","Публичный адрес шлюза и порт 8080","Только порт 22","Ничего: проброс работает сам"]', 0, 'К моменту фильтра FORWARD адрес и порт уже заменены внутренними.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 16, 2, 'Что делает MASQUERADE?', '["Заменяет адрес получателя","Шифрует трафик","Подменяет адрес отправителя внутренних пакетов на адрес выходного интерфейса","Блокирует порты"]', 2, 'Ответы возвращаются по таблице трансляций.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 16, 3, 'Какое правило между зонами разумно?', '["DMZ → LAN: разрешить всё","Интернет → DMZ: только нужные порты, DMZ → LAN: запретить","Интернет → LAN: разрешить всё","LAN → интернет: запретить"]', 1, 'Взлом сервера в DMZ не даёт доступа во внутреннюю сеть.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 16, 4, 'Клиент в LAN обращается к серверу LAN по публичному адресу и не получает ответа. В чём причина?', '["Сервер отвечает клиенту напрямую, а клиент ждёт ответ от публичного адреса","Сервер выключен","Закрыт порт 53","Устарел сертификат"]', 0, 'Помогает SNAT на шлюзе для такого трафика или раздельный DNS (hairpin NAT).');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 17, 'theory', 'Балансировка нагрузки, CDN и обратный прокси');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 17, 0, 'Чем балансировщик L7 отличается от L4?', '["L7 разбирает HTTP и может маршрутизировать по хосту, пути и заголовкам","L7 быстрее и не разбирает запросы","L7 работает только с UDP","Различий нет"]', 0, 'L4 видит лишь адреса и порты; L7 понимает запрос, но требует больше процессора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 17, 1, 'Что произойдёт без проверок здоровья, если один из трёх серверов недоступен?', '["Ничего: балансировщик сам исключит сервер","Сервер перезапустится","Примерно каждый третий запрос уйдёт в неисправный сервер и закончится ошибкой","Все запросы пойдут на оставшиеся без ошибок"]', 2, 'Балансировщик продолжает посылать запросы по кругу, в том числе и мёртвому серверу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 17, 2, 'Какой алгоритм всегда отправляет одного клиента на один и тот же сервер?', '["По кругу","Хеш по адресу клиента","Наименьшее число соединений","Случайный выбор"]', 1, 'Хеш источника (привязка сессии) полезен, но делает нагрузку неравномерной.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 17, 3, 'Обратный прокси не может достучаться до бэкенда. Какой код получит клиент?', '["401","404","301","502 Bad Gateway"]', 3, '502 говорит, что шлюз получил от вышестоящего сервера ошибку или не получил ответа.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 17, 4, 'Почему сервера «без состояния» удобнее при горизонтальном масштабировании?', '["Они не потребляют память","Они не используют сеть","Любой сервер обслуживает любого клиента: данные сессии лежат во внешнем хранилище","Они не нуждаются в балансировщике"]', 2, 'Тогда пул можно свободно увеличивать и уменьшать, а отказ сервера не теряет сессии.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 18, 'theory', 'SSH, VPN и туннели');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 18, 0, 'При подключении по SSH вы видите «REMOTE HOST IDENTIFICATION HAS CHANGED». Что делать?', '["Сразу удалить known_hosts","Уточнить у администратора, плановая ли смена ключа или возможная подмена сервера","Игнорировать и продолжить","Перезагрузить компьютер"]', 1, 'Либо ключ хоста сменили, либо сервер подменили: решать нужно после проверки, а не рефлекторно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 18, 1, 'Что делает команда ssh-copy-id?', '["Копирует закрытый ключ на сервер","Генерирует ключ хоста","Копирует файлы по SSH","Добавляет ваш открытый ключ в authorized_keys на сервере"]', 3, 'Закрытый ключ никогда не покидает ваш компьютер.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 18, 2, 'Зачем нужен ssh -J (ProxyJump)?', '["Чтобы ускорить вход","Чтобы отключить шифрование","Чтобы добраться до серверов внутренней сети через один открытый бастион","Чтобы копировать ключи"]', 2, 'Клиент сначала входит на бастион, а оттуда TCP идёт к цели; наружу внутренние серверы не публикуют.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 18, 3, 'Почему внутри VPN-туннеля MTU меньше, чем снаружи?', '["Исходный пакет упаковывают в новый, и заголовки упаковки занимают место","Туннель медленнее","Провайдер ограничивает размер","MTU не меняется"]', 0, 'Без уменьшения MTU большие пакеты не поместятся и пропадут (глава про диагностику).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 18, 4, 'Чем раздельный туннель (split tunnel) отличается от полного?', '["В VPN идёт всё, включая обычный интернет","В VPN идёт только трафик в корпоративные сети, остальное — напрямую","VPN использует два ключа","Раздельный туннель не шифруется"]', 1, 'Полный туннель отправляет в VPN всё; раздельный экономит ресурсы корпоративного шлюза.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 19, 'theory', 'Сетевые атаки и защита: спуфинг, DoS, MITM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 19, 0, 'Что делает атакующий при ARP-спуфинге?', '["Подбирает пароли","Перегружает канал","Рассылает поддельные ARP-ответы, чтобы чужой трафик шёл через его MAC","Подменяет сертификат"]', 2, 'ARP не аутентифицирует ответы: получатель верит сообщению «этот IP — это мой MAC».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 19, 1, 'Какая мера защищает сервер от SYN-флуда?', '["Отключить шифрование","Включить SYN-куки: до подтверждения сервер не хранит состояние","Увеличить MTU","Закрыть порт 53"]', 1, 'SYN-куки зашивают состояние в номер ответа, и очередь полуоткрытых соединений не переполняется.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 19, 2, 'Чем открытые DNS-резолверы опасны для третьих сторон?', '["Ничем","Они читают почту","Они ломают сертификаты","Через них усиливают DDoS: короткий запрос от имени жертвы превращается в длинный ответ"]', 3, 'Усиление — один из видов объёмных атак; резолверы нужно закрывать от посторонних.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 19, 3, 'Что главное в защите от атаки посредника (MITM)?', '["Шифрование с проверкой подлинности сервера по сертификату","Скрыть MAC-адрес","Увеличить скорость","Отключить DHCP"]', 0, 'Даже если трафик идёт через злоумышленника, он видит шифртекст и не может подделать сертификат.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 19, 4, 'Какая настройка быстрее всего снижает успех перебора паролей SSH?', '["Скрыть версию сервера","Открыть дополнительный порт","Вход только по ключам и блокировка после нескольких неудач","Отключить файрвол"]', 2, 'Ключи делают перебор бессмысленным, а блокировка гасит оставшиеся попытки.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 20, 'theory', 'Сети в облаке и контейнерах: Docker, VPC и Kubernetes');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 20, 0, 'Чем отличается публичная подсеть VPC от приватной?', '["Размером диапазона адресов","У публичной маршрут по умолчанию ведёт на Internet Gateway, у приватной — нет (или на NAT-шлюз)","Публичная всегда быстрее","Приватная не поддерживает IPv4"]', 1, 'Всё определяют таблицы маршрутов подсетей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 20, 1, 'Что делает правило группы безопасности «БД: порт 3306 из группы приложений»?', '["Открывает базу всему интернету","Блокирует исходящие соединения","Шифрует трафик","Разрешает вход на 3306 только машинам из группы приложений, остальным закрыто"]', 3, 'Источником правила служит группа, а не адреса, — это удобно при изменении числа серверов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 20, 2, 'Что происходит при публикации порта контейнера «-p 8080:80»?', '["На узле добавляется правило DNAT с порта 8080 на адрес и порт 80 контейнера","Контейнер переходит в режим host","Контейнер получает публичный IP","Отключается изоляция"]', 0, 'Docker добавляет правила netfilter: DNAT для входящих и MASQUERADE для исходящих.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 20, 3, 'Зачем в Kubernetes нужен Service, если у каждого пода свой адрес?', '["Адреса подов постоянны, и Service не нужен","Service шифрует трафик","Поды недолговечны и меняют адреса; Service даёт постоянный адрес и балансировку по готовым подам","Service заменяет DNS"]', 2, 'kube-proxy раскладывает запросы по подам, прошедшим проверку готовности.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 20, 4, 'Что даёт NetworkPolicy?', '["Увеличивает скорость сети","Выдаёт подам адреса","Подписывает образы","Ограничивает, какие поды могут общаться друг с другом"]', 3, 'Без политик все поды видят всех; политика оставляет доступ только нужным.');
